bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
root=/home/gace/Project/Gserver/projects/TGtumbler/GateApp-Bot
test "$(systemctl --user is-active gace-userbot-verify.service)" = active || exit 61
spec="$(docker exec -w /opt/videobot "$cid" node --input-type=module -e '
import pg from "pg";import {readFileSync} from "node:fs";
const e=process.env,p=readFileSync("/run/secrets/videobot_db_password","utf8").trim();
const db=new pg.Pool({host:e.VIDEOBOT_DB_HOST,database:e.VIDEOBOT_DB_NAME,user:e.VIDEOBOT_DB_USER,password:p,max:1,connectionTimeoutMillis:5000});
try {const q=await db.query("SELECT b.free_message_ids,b.paid_message_id,b.topic_id,l.price_stars FROM videobot_post_receipts a JOIN videobot_listings l ON l.listing_id=a.listing_id JOIN videobot_post_receipts b ON b.listing_id=l.listing_id AND b.revision=l.revision WHERE a.paid_message_id=4691 AND a.free_message_ids=ARRAY[4689,4690]::bigint[] AND b.status=$1",["sent"]);
if(q.rowCount!==1)process.exitCode=70;
else{const r=q.rows[0];console.log(JSON.stringify({ids:[...r.free_message_ids,r.paid_message_id].map(Number),thread:Number(r.topic_id),price:Number(r.price_stars)}));}
}catch{process.exitCode=79}finally{await db.end()}
')" || exit 62
GACE_SPEC="$spec" python3 -B - <<'PY'
import asyncio,json,os,pathlib,uuid,sys
data=json.loads(os.environ["GACE_SPEC"])
sock=pathlib.Path("/home/gace/Project/Gserver/projects/TGtumbler/GateApp-Bot/deploy/secrets/userbot_verify.sock")
async def read(ids):
 r,w=await asyncio.open_unix_connection(str(sock))
 try:
  k=uuid.uuid4().hex
  q={"request_id":k,"action":"video_sale_readback","chat_id":-1002373696859,
     "thread_id":data["thread"],"message_ids":ids}
  w.write((json.dumps(q)+"\n").encode());await w.drain()
  answer=json.loads(await asyncio.wait_for(r.readline(),40))
  if answer.get("request_id")!=k or answer.get("status")!="PASS":raise RuntimeError("READBACK_INVALID")
  return answer
 finally:w.close();await w.wait_closed()
try:
 new=asyncio.run(read(data["ids"]))
 old=asyncio.run(read([4689,4690,4691]))
 if not (new["free_album_grouped"] and new["paid_media_native"] and new["paid_stars"]==data["price"]):sys.exit(71)
 print("NEW_READER_PREVIEW="+str(new.get("preview_for_reader")))
 print("OLD_READER_PREVIEW="+str(old.get("preview_for_reader")))
 if new.get("preview_for_reader") is True:sys.exit(0)
 if new.get("preview_for_reader") is False:sys.exit(72)
 sys.exit(73)
except Exception:sys.exit(79)
PY
